      "file": "Hold.java",
      "body": "import java.util.concurrent.atomic.AtomicReference;\n\n/** A time-boxed claim on stock. Status moves out of HELD exactly once. */\npublic final class Hold {\n    public enum Status { HELD, CONFIRMED, RELEASED, EXPIRED }\n\n    private final String id;\n    private final String userId;\n    private final String productId;\n    private final int qty;\n    private final long amountCents;\n    private final long expiresAtMillis;\n    private final AtomicReference<Status> status = new AtomicReference<>(Status.HELD);\n\n    public Hold(String id, String userId, String productId, int qty, long amountCents, long expiresAtMillis) {\n        this.id = id;\n        this.userId = userId;\n        this.productId = productId;\n        this.qty = qty;\n        this.amountCents = amountCents;\n        this.expiresAtMillis = expiresAtMillis;\n    }\n\n    /** Compare-and-set: of two racing callers (confirm vs expire), exactly one wins. */\n    public boolean transition(Status from, Status to) { return status.compareAndSet(from, to); }\n\n    public String id()              { return id; }\n    public String userId()          { return userId; }\n    public String productId()       { return productId; }\n    public int qty()                { return qty; }\n    public long amountCents()       { return amountCents; }\n    public long expiresAtMillis()   { return expiresAtMillis; }\n    public Status status()          { return status.get(); }\n\n    @Override public String toString() { return id + \"(\" + userId + \", \" + status.get() + \")\"; }\n}\n"
